class HeartRateMonitor:
    """Base class for heart rate monitors."""

    def __init__(self, on_hr: Callable[[int], None], on_error: Optional[Callable[[str], None]] = None):
        self.on_hr = on_hr
        self.on_error = on_error or (lambda msg: print(f"HR Monitor Error: {msg}"))
        self._stop_event = threading.Event()
        self._thread: Optional[threading.Thread] = None

    def start(self):
        raise NotImplementedError

    def stop(self):
        self._stop_event.set()
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=2)

    def _report_error(self, msg: str):
        """Report error to callback"""
        try:
            self.on_error(msg)
        except Exception:
