class SimulatedHeartRateMonitor(HeartRateMonitor):
    """Simulates heart rate with a smooth sinusoidal wave + noise."""

    def __init__(self, on_hr: Callable[[int], None], on_error: Optional[Callable[[str], None]] = None,
                 base: int = 75, amplitude: int = 25, period_s: float = 30.0):
        super().__init__(on_hr, on_error)
        self.base = base
        self.amplitude = amplitude
        self.period_s = period_s

    def start(self):
        def run():
            t0 = time.time()
            while not self._stop_event.is_set():
                t = time.time() - t0
                bpm = self.base + self.amplitude * math.sin(2 * math.pi * t / self.period_s)
                bpm += random.uniform(-2, 2)  # add small noise
                self.on_hr(max(40, min(200, int(bpm))))
                time.sleep(1.0)

        self._stop_event.clear()
        self._thread = threading.Thread(target=run, daemon=True, name="SimulatedHR")
        self._thread.start()


class BLEHeartRateMonitor(HeartRateMonitor):
    """BLE heart rate monitor using the standard Heart Rate Measurement characteristic."""

    def __init__(self, on_hr: Callable[[int], None], on_error: Optional[Callable[[str], None]] = None,
                 address: Optional[str] = None, scan_timeout: float = 10.0, connect_timeout: float = 15.0):
        if not BLEAK_AVAILABLE:
            raise ImportError("bleak is not installed. Install with 'pip install bleak'.")
        super().__init__(on_hr, on_error)
        self.address = address
        self.scan_timeout = scan_timeout
        self.connect_timeout = connect_timeout
        self._hr_char_uuid = HR_MEASUREMENT_CHAR_UUID
        self._retry_count = 0
        self._max_retries = 3

    def start(self):
        def run_loop():
            try:
                asyncio.run(self._runner())
            except Exception as e:
                self._report_error(f"BLE thread error: {str(e)}")

        self._stop_event.clear()
        self._retry_count = 0
        self._thread = threading.Thread(target=run_loop, daemon=True, name="BLEHeartRate")
        self._thread.start()

    async def _find_device(self):
        """Scan for BLE heart rate devices"""
        try:
            print(f"Scanning for BLE devices (timeout: {self.scan_timeout}s)...")
            devices = await BleakScanner.discover(timeout=self.scan_timeout)
            print(f"Found {len(devices)} BLE devices")

            if not devices:
                self._report_error("No BLE devices found. Make sure your device is on and in range.")
                return None

            # If specific address provided, look for it
            if self.address:
                for d in devices:
                    if d.address.lower() == self.address.lower():
                        print(f"Found target device: {d.name} ({d.address})")
                        return d
                self._report_error(f"Device {self.address} not found. Available: {[d.name for d in devices[:5]]}")
                return None

            # Best-effort: pick device whose name hints at HR
            preferred_keywords = ["polar", "garmin", "fitbit", "wahoo", "coros", "hr", "heart", "chest", "band"]
            for d in devices:
                name = (d.name or "").lower()
                if any(k in name for k in preferred_keywords):
                    print(f"Auto-selected HR device: {d.name} ({d.address})")
                    return d

            # List available devices for user
            device_names = [f"{d.name or 'Unknown'} ({d.address})" for d in devices[:10]]
            self._report_error(f"No HR device auto-detected. Available: {', '.join(device_names)}")
            return None

        except Exception as e:
            self._report_error(f"BLE scan error: {str(e)}")
            return None

    async def _runner(self):
        """Main BLE connection and notification loop with retry logic"""
        while not self._stop_event.is_set() and self._retry_count < self._max_retries:
            try:
                device = await self._find_device()
                if not device:
                    self._retry_count += 1
                    if self._retry_count < self._max_retries:
                        print(f"Retrying device scan ({self._retry_count}/{self._max_retries})...")
                        await asyncio.sleep(2)
                    continue

                print(f"Connecting to {device.name or device.address} (timeout: {self.connect_timeout}s)...")

                try:
                    async with BleakClient(device, timeout=self.connect_timeout) as client:
                        if not client.is_connected:
                            self._report_error("Failed to establish connection")
                            self._retry_count += 1
                            continue

                        print(f"Connected to {device.name or device.address}")
                        self._retry_count = 0  # Reset on successful connection

                        # Setup notification handler
                        def handle_hr(_, data: bytearray):
                            try:
                                flags = data[0]
                                hr_16 = flags & 0x01
                                if hr_16:
                                    hr = int.from_bytes(data[1:3], byteorder="little")
                                else:
                                    hr = data[1]
                                if 20 <= hr <= 250:
                                    self.on_hr(int(hr))
                            except Exception:
                                pass

                        # Start notifications
                        await self._start_hr_notifications(client, handle_hr)

                        # Loop until stop requested or disconnected
                        while not self._stop_event.is_set() and client.is_connected:
                            await asyncio.sleep(0.5)

                        # Cleanup
                        try:
                            await client.stop_notify(self._hr_char_uuid)
                        except Exception:
                            pass

                except asyncio.TimeoutError:
                    self._retry_count += 1
                    self._report_error(f"Connection timeout. Retry {self._retry_count}/{self._max_retries}")
                    if self._retry_count < self._max_retries:
                        await asyncio.sleep(3)
                    continue

                except BleakError as e:
                    self._retry_count += 1
                    self._report_error(f"BLE error: {str(e)}. Retry {self._retry_count}/{self._max_retries}")
                    if self._retry_count < self._max_retries:
                        await asyncio.sleep(3)
                    continue

            except Exception as e:
                self._retry_count += 1
                self._report_error(f"Unexpected error: {str(e)}")
                if self._retry_count < self._max_retries:
                    await asyncio.sleep(3)

        if self._retry_count >= self._max_retries:
            self._report_error("Max retries reached. Please check your device and try again.")

    async def _start_hr_notifications(self, client, handler):
        """Start HR notifications, with fallback for non-standard devices"""
        try:
            await client.start_notify(HR_MEASUREMENT_CHAR_UUID, handler)
            self._hr_char_uuid = HR_MEASUREMENT_CHAR_UUID
            print("Started HR notifications")
            return
        except Exception as e:
            print(f"Standard HR UUID failed: {e}, trying dynamic discovery...")

        # Fallback: dynamically find HR characteristic
        try:
            svcs = await client.get_services()
            for service in svcs:
                if service.uuid.lower() == HR_SERVICE_UUID:
                    for char in service.characteristics:
                        if "notify" in char.properties:
                            try:
                                await client.start_notify(char.uuid, handler)
                                self._hr_char_uuid = char.uuid
                                print(f"Started HR notifications on {char.uuid}")
                                return
                            except Exception:
                                continue

            self._report_error("Could not find HR notification characteristic")
        except Exception as e:
            self._report_error(f"Service discovery failed: {str(e)}")

