        self.root.after(0, update_status)

        # Only fallback if error indicates connection failure (not just status update)
        if "timeout" in str(err).lower() or "max retries" in str(err).lower() or "not found" in str(err).lower():
            # Stop current monitor if any
            if self.hr_monitor:
                try:
                    self.hr_monitor.stop()
                except Exception:
                    pass
                self.hr_monitor = None

            # Start simulator if available
            if SimulatedHeartRateMonitor:
                sim = SimulatedHeartRateMonitor(on_hr=self._on_hr)
                sim.start()
                self.hr_monitor = sim
                self._hr_ema = None
                self.root.after(0, lambda: self.status_text.set("Using simulated heart rate"))
            else:
                self.root.after(0, lambda: messagebox.showwarning("Heart Rate", f"BLE failed: {err}"))
                self.enable_heart_rate.set(False)
    except Exception as e:
        print(f"Error in _on_hr_error handler: {e}")
